#!/usr/bin/env python3
"""Real offline Chromium QA for the expanded laboratory, including Blob workers."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,csv,io,time,shutil,argparse
parser=argparse.ArgumentParser();parser.add_argument("--part",choices=["core","connections","population"],default="core");args=parser.parse_args()
ROOT=Path(__file__).resolve().parents[1];checks=[];errors=[];requests=[];start=time.time()
def check(name,ok,details=None):
 checks.append(dict(name=name,passed=bool(ok),details=details));print(name,ok,flush=True)
 if not ok:raise AssertionError(name)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 context=browser.new_context(viewport={'width':1440,'height':1100},accept_downloads=True)
 page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url))
 page.set_content((ROOT/'optogenetics-laboratory.html').read_text(),wait_until='load');page.wait_for_function('!!window.OptoAdvanced')
 def ev(s,arg=None):return page.evaluate(s,arg)
 def download(selector):
  with page.expect_download() as d:page.click(selector)
  return Path(d.value.path()).read_text()
 def run():
  page.click('#adv-run');page.wait_for_function('!OptoAdvanced.isBusy()',timeout=90000)
  assert ev('!!OptoAdvanced.getResult()'),page.locator('#adv-error').text_content()
 def short():ev('''()=>{let c=OptoAdvanced.getConfig();c.experiment.durationMs=80;c.experiment.onsetMs=20;c.experiment.trainDurationMs=40;c.experiment.dtMs=.01;c.drive.endMs=75;OptoAdvanced.setConfig(c);}''')
 check('Expanded workspace starts without automatic expensive calculation',page.locator('#advanced-panel').is_visible() and ev('OptoAdvanced.getResult()===null&&!OptoAdvanced.isBusy()'))
 check('Desktop has no horizontal overflow',ev('document.documentElement.scrollWidth<=innerWidth+1'))
 check('Five workspaces remain accessible',page.locator('nav button').count()==5)
 if args.part=='core':
  short();run()
  check('Matched inhibition is numerically calculated',ev('OptoAdvanced.getResult().summaries[0].illuminatedEvents===0 && OptoAdvanced.getResult().summaries[0].baselineEpochEvents===2'))
  check('Dynamic chloride increases in this positive-current assay',ev('OptoAdvanced.getResult().cells[0].somaChlorideMm.at(-1)>5'))
  check('Trace plot and comparison are rendered',page.locator('#adv-vplot svg path').count()>=2)
  ev('OptoAdvanced.setTime(25)');check('Shared cursor reports active light', 'light on' in page.locator('#adv-scene-state').inner_text().lower())
  ev('OptoAdvanced.setTime(65)');check('Shared cursor reports light offset', 'light off' in page.locator('#adv-scene-state').inner_text().lower())
  setup=download('#adv-save');saved=json.loads(setup);check('Saved experiment has versioned model provenance',saved['schema']=='bts-opto-experiment/3' and len(saved['sourceCommit'])==40)
  full=json.loads(download('#adv-json'));check('Result JSON retains all five compartment recordings and matched controls',all(len(full['cells'][0][k])==full['cells'][0]['n']*full['cells'][0]['frames'] for k in ['voltageMv','photocurrentNa','effectiveOpen','chlorideMm','chlorideReversalMv']) and len(full['control'])==1)
  rows=list(csv.DictReader(io.StringIO(download('#adv-csv'))));check('CSV rows match recording frames and include chloride/temperature columns',len(rows)==161 and 'soma_Cl_mM' in rows[0] and 'soma_deltaT_C' in rows[0])
  ev("()=>{const x=document.getElementById('adv-irradiance');x.value=0.5;x.dispatchEvent(new Event('change'));}")
  check('Parameter edit clears stale recordings and disables export',ev('OptoAdvanced.getResult()===null') and page.locator('#adv-json').is_disabled())
  ev("()=>{const x=document.getElementById('adv-ci');x.value='';x.dispatchEvent(new Event('change'));}")
  check('Invalid blank numeric input blocks computation without crashing renderer',page.locator('#adv-run').is_disabled() and page.locator('#adv-error').is_visible())
  ev("()=>{const x=document.getElementById('adv-ci');x.value=5;x.dispatchEvent(new Event('change'));}")
  check('Corrected numeric input restores run',page.locator('#adv-run').is_enabled())
  page.set_input_files('#adv-file',{'name':'experiment.json','mimeType':'application/json','buffer':setup.encode()});page.wait_for_function('document.querySelector("#adv-import-status").textContent.includes("Experiment loaded")')
  check('Experiment file round-trips through visible input',ev('OptoAdvanced.getConfig()')==saved['config'])
  before=ev('OptoAdvanced.getConfig()');page.set_input_files('#adv-file',{'name':'bad.json','mimeType':'application/json','buffer':b'{"schema":"unsupported"}'});page.wait_for_function('!document.querySelector("#adv-error").hidden')
  check('Unsupported import leaves previous setup unchanged',ev('OptoAdvanced.getConfig()')==before)
  page.set_input_files('#adv-file',{'name':'huge.json','mimeType':'application/json','buffer':b' '*1000001});page.wait_for_function('document.querySelector("#adv-error").textContent.includes("1 MB")');check('Oversized JSON import rejected',ev('OptoAdvanced.getConfig()')==before)
  page.click('#adv-run');page.click('#adv-cancel');check('Cancellation terminates worker and clears result',ev('!OptoAdvanced.isBusy()&&OptoAdvanced.getResult()===null'))
  run();check('New Blob worker runs successfully after cancellation',ev('OptoAdvanced.getResult().cells.length===1'))
  # desktop inhibition screenshot
  ev('OptoAdvanced.setTime(45)');page.evaluate('scrollTo(0,0)');page.screenshot(path=str(ROOT/'previews/v3-chloride.png'),full_page=True)
 if args.part=='connections':
  # Repeated edits to cell-specific opsins must not write a stale closure.
  page.locator('#adv-cell-editors select').evaluate('(e)=>e.closest("details").open=true');page.select_option('#adv-cell-editors select','chronos');page.select_option('#adv-cell-editors select','gtacr2');check('Repeated cell-specific opsin edits affect current configuration',ev('OptoAdvanced.getConfig().population.cells[0].opsin==="gtacr2"'))
  page.select_option('#adv-preset','microled');check('MicroLED preset has three explicit rectangular sources',ev('OptoAdvanced.getConfig().device.emitters.length===3&&OptoAdvanced.getConfig().source.kind==="microled"'))
  ev("()=>{for(const a of ['x','y','z'])document.getElementById('adv-n'+a).value=0;document.getElementById('adv-nx').dispatchEvent(new Event('change'));}")
  check('Zero LED normal is rejected before solver',page.locator('#adv-error').is_visible() and page.locator('#adv-run').is_disabled())
  page.select_option('#adv-preset','chloride');short()
  for opsin,wave in [('chronos',500),('chrimsonr',590),('gtacr2',470)]:
   ev('''d=>{const c=OptoAdvanced.getConfig();c.opsin=d.opsin;c.population.cells[0].opsin=d.opsin;c.experiment.mode='clamp';c.experiment.clampMv=-60;c.source.wavelengthNm=d.wave;c.drive.currentNa=0;c.matchedControl=false;OptoAdvanced.setConfig(c);}''',dict(opsin=opsin,wave=wave));run()
   check(opsin+' reduced model calculates a clamped photocurrent',ev('OptoAdvanced.getResult().cells[0].somaVoltageMv.every(x=>x===-60)&&OptoAdvanced.getResult().cells[0].totalPhotocurrentNa.some(x=>Math.abs(x)>1e-4)'))
  # Explicit imports and inert hostile labels.
  page.click('#adv-example-device');check('Native device preview does not change source before apply',ev('OptoAdvanced.getImportPreview().kind==="device" && OptoAdvanced.getConfig().source.kind==="uniform"'))
  page.click('#adv-apply-import');check('Native device application changes source explicitly',ev('OptoAdvanced.getConfig().source.kind==="microled"'))
  page.click('#adv-example-designer');check('Designer preview preserves electrode roles',ev('OptoAdvanced.getImportPreview().device.emitters.length===0') and page.locator('#adv-import-table input').count()==4)
  page.locator('#adv-import-table input').nth(0).check();page.locator('#adv-import-table input').nth(2).check();page.click('#adv-convert')
  check('Only selected contacts become optical emitters',ev('OptoAdvanced.getConfig().device.emitters.length===2&&OptoAdvanced.getConfig().device.contacts.length===4'))
  d=json.loads(download('#adv-device-export'));check('Converted device exports editable assumptions and original layout',d['metadata']['conversion']['selectedContactIds']==['E1','E3'] and d['emitters'][0]['wavelengthNm']==470 and 'original' in d['metadata'])
  ev('''()=>OptoAdvanced.importObject({schema:'bts-neural-interface',version:1,units:'um',name:'<img src=x onerror=window.pwned=1>',contacts:[{id:'<script>bad</script>',x:0,y:0,w:22,h:22,shape:'square'}]})''');check('Imported names rendered as inert text, not markup',ev('!window.pwned') and '<script>bad</script>' in page.locator('#adv-import-table').inner_text())
  page.click('#adv-reject-import');before=ev('OptoAdvanced.getConfig().device.emitters')
  ev("()=>OptoAdvanced.importObject({schema:'microfabrication-1',config:{metalThicknessNm:200}})");page.click('#adv-apply-import')
  check('Cleanroom recipe attaches only provenance; emitter physics unchanged',ev('OptoAdvanced.getConfig().device.emitters')==before and ev('OptoAdvanced.getConfig().device.metadata.cleanroomRecipe.config.metalThicknessNm===200'))
 if args.part=='population':
  page.select_option('#adv-preset','population');short();run()
  check('Four independent neuron solves and thermal arrays complete',ev('OptoAdvanced.getResult().cells.length===4&&OptoAdvanced.getResult().thermal.pointsCount===1144'))
  check('Cells sample different actual microLED fields',ev('new Set(OptoAdvanced.getResult().cells.map(c=>c.lightMwMm2[0])).size===4'))
  check('Population events populate raster and table',page.locator('#adv-summary tbody tr').count()==4 and page.locator('#adv-raster svg').count()==1)
  check('Thermal energy ledger closes',ev('OptoAdvanced.getResult().thermal.diagnostics.energyResidualJ<1e-12'))
  page.select_option('#adv-cell','2');check('Cell inspector changes the readout', 'cell-3' in page.locator('#adv-inspect-value').inner_text())
  for overlay in ['light','conductance','chloride','ecl','heat','voltage']:
   page.select_option('#adv-overlay',overlay);check('Replay overlay '+overlay+' renders',page.locator('#adv-legend-max').inner_text()!='')
  page.locator('#adv-heatmap').evaluate('(e)=>e.closest("details").open=true');page.locator('#adv-cell').select_option('0');ev('OptoAdvanced.setTime(24)')
  check('Heat map is a computed final-grid rendering',page.locator('#adv-heat-ledger').inner_text().startswith('Deposited:'))
  page.evaluate('scrollTo(0,0)');page.screenshot(path=str(ROOT/'previews/v3-population-light.png'),full_page=True)
  page.click('#theme');check('Dark palette toggles without recalculation',ev('document.documentElement.dataset.theme==="dark"&&!!OptoAdvanced.getResult()'))
  page.screenshot(path=str(ROOT/'previews/v3-population-dark.png'),full_page=True)
  page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(200)
  check('Mobile layout has no document horizontal overflow',ev('document.documentElement.scrollWidth<=innerWidth+1'),ev('({w:innerWidth,scroll:document.documentElement.scrollWidth})'))
  page.evaluate('()=>{document.querySelectorAll(".adv-controls > details").forEach(d=>d.open=false);scrollTo(0,0)}');page.screenshot(path=str(ROOT/'previews/v3-mobile-dark.png'),full_page=True)
  check('Mobile playback and cell selector remain available',page.locator('#adv-play').is_enabled() and page.locator('#adv-cell').count()==1)
  page.click('#adv-play');page.wait_for_timeout(400);page.click('#adv-play');check('Replay advances shared time cursor',ev('Number(document.querySelector("#adv-time").value)>48'))
  # Legacy modes are still executable, not just visible.
  page.set_viewport_size({'width':1440,'height':1100});page.click('#tab-neuron')
  ev("()=>{let c=OptoLab.getConfig();OptoLab.setConfig({...c,protocol:'single',durationMs:80,onsetMs:20,pulseWidthMs:5,dtMs:.01});OptoLab.run()}")
  page.wait_for_function('!OptoLab.isBusy()',timeout=60000);check('Legacy ChR2 neuron still produces its tested single spike',ev('OptoLab.getResult().spikes.length===1'))
  page.click('#tab-clamp');check('Legacy ideal clamp remains accessible',page.locator('#experiment-panel').is_visible())
  page.click('#tab-sweep');check('Legacy response-map workspace preserved',page.locator('#sweep-panel').is_visible())
  page.click('#tab-evidence');check('Evidence workspace preserved',page.locator('#evidence-panel').is_visible())
  page.click('#tab-advanced');check('Returning to expanded lab retains its calculated result',ev('!!OptoAdvanced.getResult()'))
 check('No uncaught browser exceptions',not errors,errors)
 external=[r for r in requests if r.startswith(('http:','https:'))];check('No runtime network requests',not external,external)
 report=dict(browser=browser.version,execution='Playwright set_content; real Chromium JavaScript and inline Blob workers; physical iPhone/Safari not tested',passed=len(checks),failed=0,checks=checks,elapsedSeconds=time.time()-start)
 (ROOT/f'validation/phase3/browser-{args.part}.json').write_text(json.dumps(report,indent=2));browser.close()
